                                       _RE_REF_BRACKET, _RE_REF_NUM, _REF_MAX_ENTRY)

def longest_chain(cands):
    best = []
    for i, (num, pos) in enumerate(cands):
        cur = [(num, pos)]; want = num + 1
        for n2, p2 in cands[i+1:]:
            if n2 in (want, want + 1):
                cur.append((n2, p2)); want = n2 + 1
        if len(cur) > len(best):
            best = cur
    return best

def starts_new(stream):
    best = []
    for pattern in (_RE_REF_BRACKET, _RE_REF_NUM):
        cands = [(int(m.group(1)), m.start()) for m in pattern.finditer(stream)]
        chain = longest_chain(cands)
        if len(chain) > len(best):
            best = chain
    return [p for _, p in best]

rows = json.loads(pathlib.Path("refs_blocks.json").read_text())
# runs: 连续 refs（无 band）；band 的 refs 作为隔断
