            texts.append(" ".join(stream[pos:end].split()))
        tot += len(texts)
        print(f"      条数 {len(texts)}，最长 {max(len(t) for t in texts)} 字符，"
              f"首条尾部 {texts[-1][-60:]!r}")
        print(f"      段首前导（不参与合并）: {stream[:st[0]].strip()[:70]!r}")
