@router.post("/papers/{paper_id}/convert", status_code=202)
def retrigger(paper_id: int, background: BackgroundTasks,
              conn: sqlite3.Connection = Depends(get_conn),
              user: dict[str, Any] = Depends(current_user)) -> dict[str, Any]:
    """失败重试入口（§5.7：不阻塞其它文献）。"""
    paper = require_paper(conn, paper_id, user)
    if paper["conv_state"] == "doing":
        raise HTTPException(status.HTTP_409_CONFLICT, "该文献正在转换中")
    with tx(conn):
        # `conv_attempts` 归零：**人工主动重试不该被自动护栏挡住**。
        # `docs/design.md` 的原话是「超限置 failed **待人工重试**」—— 人工重试若不能重置
        # 计数，这句话就是空话（用户点到第 4 次会永远得到"超过最大重试次数"）。
        # ⚠️ 修 `claim_paper` 之前计数恒为 0，这条护栏从未生效（2026-09-15 一并修）。
        conn.execute(
            "UPDATE papers SET conv_state='queued', conv_error=NULL, conv_attempts=0 WHERE id=?",
            (paper_id,),
        )
    fingerprint = None
    if paper["pdf_path"] and Path(paper["pdf_path"]).exists():
        fingerprint = _pdf_fingerprint(Path(paper["pdf_path"]))
    background.add_task(convert_paper, paper_id, fingerprint)
    return {"ok": True, "conv_state": "queued"}


@router.post("/papers/{paper_id}/reextract", status_code=202)
def reextract(paper_id: int, background: BackgroundTasks,
              conn: sqlite3.Connection = Depends(get_conn),
              user: dict[str, Any] = Depends(current_user)) -> dict[str, Any]:

/** 文献库 —— 原型的 `renderLibrary`：筛选 chips（带计数）+ 排序 + 文献表。
 *
 * 只呈现**当前计划**的文献（原型 `papers()` 的语义）。
 * 顶栏搜索把关键词写进 `?q=`，本页从 URL 读 —— 这样"搜到一半刷新"不会丢条件。
 *
 * 表格列刻意与原型一致：标题/作者 · 发表 · 标签 · 中文版 · 状态 · 进度。
 * 「中文版」列是可点的**动作**（待转换 → 生成；失败 → 重试），不是只读徽标：
 * 转换本来就是这台工作台最容易卡住的一环，让它一步可达。
 */

import { useCallback, useMemo, useState } from 'react'
import { Link, useNavigate, useSearchParams } from 'react-router-dom'

import { api } from '../api'
import { CONV, clip, fmtDate, isDone, relTime, STATUS, STATUS_ORDER } from '../vocab'
import { Pill } from '../components'
import { PaperMetaDrawer } from './PaperMetaDrawer'
import { useLink, useReadonly } from '../shareContext'
import { NoPlan, TopBar } from '../shell'
import { usePlan } from '../planContext'
import type { Paper, PaperStatus } from '../types'

/** 只到「月-日」：文献库单元格很窄，年份在这个场景没有信息量（都是今年入库的）。 */
const shortDay = (iso: string | null | undefined): string => {
  const d = fmtDate(iso)
  return d === '—' ? '—' : d.slice(5)
}

type Sort = 'recent' | 'year' | 'progress' | 'title'

const SORTS: Array<{ k: Sort; label: string }> = [
  { k: 'recent', label: '最近更新' },
  { k: 'year', label: '发表年份' },
  { k: 'progress', label: '阅读进度' },
  { k: 'title', label: '标题' },
]

/** 确认框里指代这篇文献的方式。`original` 是上传时的文件名占位（⑲），念出来毫无信息。 */
function paperLabel(p: Paper): string {
  return p.title && p.title !== 'original' ? `《${p.title}》` : `文献 #${p.id}`
}

export function LibraryPage() {
  const { plan, papers, loading, reload } = usePlan()
  const [params, setParams] = useSearchParams()
  const nav = useNavigate()
  const link = useLink()
  const readonly = useReadonly()

  const [sort, setSort] = useState<Sort>('recent')
  const [filter, setFilter] = useState<'all' | PaperStatus>('all')
  const [busy, setBusy] = useState<number | null>(null)
  const [editing, setEditing] = useState<Paper | null>(null)

  const q = params.get('q') || ''

  const byStatus = useMemo(() => {
    const out: Record<string, number> = { all: papers.length }
    STATUS_ORDER.forEach((k) => { out[k] = papers.filter((p) => p.status === k).length })
    return out
  }, [papers])

  const shown = useMemo(() => {
    let list = [...papers]
    const needle = q.trim().toLowerCase()
    if (needle) {
      list = list.filter((p) =>
        [p.title, p.authors || '', p.venue || '', ...(p.tags || [])]
          .join(' ').toLowerCase().includes(needle))
    }
    if (filter !== 'all') list = list.filter((p) => p.status === filter)
    const cmp: Record<Sort, (a: Paper, b: Paper) => number> = {
      recent: (a, b) => b.created_at.localeCompare(a.created_at),
      year: (a, b) => (b.year || 0) - (a.year || 0),
      progress: (a, b) => b.progress - a.progress,
      title: (a, b) => (a.title || '').localeCompare(b.title || ''),
    }
    return list.sort(cmp[sort])
  }, [papers, q, filter, sort])

  const convert = useCallback(async (p: Paper) => {
    setBusy(p.id)
    try {
      await api.retryConvert(p.id)
      await reload()
    } catch { /* 失败原因会落在 conv_error 里，下次刷新可见 */ }
    finally { setBusy(null) }
  }, [reload])

  // 删除文献：与「删除计划」同一套约定（`window.confirm` 说清不可撤销）。
  // 文案必须点名**连带消失的东西** —— 译文、笔记、分享里看到的内容都靠这篇，
  // 只说"删除文献？"会让人以为只是从列表里去掉。
  const remove = useCallback(async (p: Paper) => {
    const name = paperLabel(p)
    if (!window.confirm(`删除${name}？其译文、笔记与该文献的图片都会一并删除，此操作不可撤销。`)) return

/** 计划上下文 —— 侧栏的「当前计划」是**全局状态**，而路由只带 paperId（不带 planId）。
 *
 * 为什么要这一层（而不是每个页面各自取一遍）：
 * 1. 总览 / 文献库 / 看板全部只呈现**当前计划**（原型的 `papers()` 就是这个语义）；
 * 2. 侧栏的进度卡、导航计数、顶栏副标题都依赖同一份 `papers`；
 * 3. 计划切换必须能**整站生效**（切完停在同一条路由上，数据换掉）—— 分享态例外，
 *    ⑩ 是单计划视图，切换器里只有一个计划且不可展开（原型 `SHARE.active` 同款）。
 *
 * **只读分享复用这一整层**（决策⑩「和分享者看到的一模一样」）：只在 `load()`
 * 里把取数口换成 `/api/shares/{token}*` 白名单，页面组件完全不知情。
 *
 * `reload()` 由各页面在写完数据后调用（改状态、导入、重试转换），
 * 走同一个 ref 计数，避免每页自己维护一份 papers 副本而彼此不一致。
 */

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import type { ReactNode } from 'react'
import { useLocation, useNavigate, useParams } from 'react-router-dom'

import { api } from './api'
import { useAuth } from './auth'
import { useShare } from './shareContext'
import type { Paper, Plan } from './types'

const LS_KEY = 'papershelf.activePlanId'

interface PlanValue {
  plans: Plan[]
  /** 当前计划；一个计划都没有时为 null */
  plan: Plan | null
  papers: Paper[]
  loading: boolean
  error: string
  /** 重新拉计划列表 + 当前计划的文献（写完数据后调用） */
  reload: () => Promise<void>
  switchPlan: (id: number) => void
  setPlanLocal: (p: Plan) => void
}

const Ctx = createContext<PlanValue | null>(null)

export function PlanProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth()
  const share = useShare()
  // ⚠️ `share` 是 useMemo 出来的对象，`meta` 一变它就换新身份。若把它整个放进
  //    `load` 的依赖，取回 meta → 换新 share → load 换新 → effect 重跑 → 再取一次，
  //    每轮多一次请求。这里只取**稳定**的两样：token 与 setMeta。
  const shareToken = share?.token
  const setShareMeta = share?.setMeta
  const nav = useNavigate()
  const loc = useLocation()
  const route = useParams()

  const [plans, setPlans] = useState<Plan[]>([])
  const [papers, setPapers] = useState<Paper[]>([])
  const [activeId, setActiveId] = useState<number | null>(() => {
    const v = Number(localStorage.getItem(LS_KEY))
    return Number.isFinite(v) && v > 0 ? v : null
  })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const seq = useRef(0)

  // 路由里若显式带了 planId（/plans/:planId），它优先于本地记忆
  const routePlanId = Number(route.planId)
  const routePlanValid = Number.isFinite(routePlanId) && routePlanId > 0

  const load = useCallback(async (targetId: number | null, quiet = false) => {
    // 分享态：匿名也能取数，走白名单端点；登录态：先看有没有登录
    if (!shareToken && !user) { setPlans([]); setPapers([]); setLoading(false); return }
    const mine = ++seq.current
    if (!quiet) setLoading(true)
    try {
      if (shareToken) {
        const [list, payload] = await Promise.all([
          api.sharedPlans(shareToken), api.sharedPlan(shareToken),
        ])
        if (mine !== seq.current) return
        setPlans(list)
        setActiveId(payload.plan.id)

