.emrg/sessions/s_260910_1634_1ef06219/history_260910.jsonl:933:{"timestamp": "2026-09-10T20:51:57.533807", "type": "message", "role": "assistant", "content": "", "tool_calls": [{"id": "call_00_ET_em2ZqqdbvOmwP2V21dSM2621", "type": "function", "function": {"name": "write", "arguments": "{"content": "/** 计划详情 —— 文献列表 + 导入抽屉 + 分享管理 + 术语表（⑫⑰⑱⑲⑩⑪）。\n *\n * 转换状态是页面里唯一需要**轮询**的东西（决策② 全自动无人值守）：\n * 有文献处于 queued / doing 时每 3 秒重取一次列表，其余情况不轮询。\n */\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from 'react'\nimport { Link, useParams } from 'react-router-dom'\n\nimport { api } from '../api'\nimport type { GlossaryEntry, Paper, PaperStatus, Plan, Share } from '../types'\n\nconst STATUS_LABEL: Record<PaperStatus, string> = {\n  unread: '未读', reading: '在读', read: '已读', reviewed: '已精读',\n}\nconst CONV_LABEL: Record<Paper['conv_state'], string> = {\n  none: '未转换', queued: '排队中', doing: '转换中', done: '已就绪', failed: '转换失败',\n}\n\nfunction ConvChip({ paper, onRetry }: { paper: Paper; onRetry: (id: number) => void }) {\n  const cls = paper.conv_state === 'done' ? 'ok'\n    : paper.conv_state === 'failed' ? 'danger'\n      : paper.conv_state === 'none' ? '' : 'warn'\n  return (\n    <span className=\"row\" style={{ gap: 6 }}>\n      <span className={`chip ${cls}`}>{CONV_LABEL[paper.conv_state]}</span>\n      {paper.conv_state === 'failed' && (\n        <>\n          <button className=\"ghost\" style={{ fontSize: 12, padding: '1px 6px' }}\n                  title={paper.conv_error || ''} onClick={() => onRetry(paper.id)}>重试</button>\n        </>\n      )}\n    </span>\n  )\n}\n\nfunction Drawer({ title, onClose, children }: {\n  title: string; onClose: () => void; children: React.ReactNode\n}) {\n  useEffect(() => {\n    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }\n    window.addEventListener('keydown', onKey)\n    return () => window.removeEventListener('keydown', onKey)\n  }, [onClose])\n  return (\n    <>\n      <div className=\"drawer-mask\" onClick={onClose} />\n      <aside className=\"drawer\">\n        <header>\n          <strong style={{ flex: 1 }}>{title}</strong>\n          <button className=\"ghost\" onClick={onClose}>关闭</button>\n        </header>\n        <div className=\"body\">{children}</div>\n      </aside>\n    </>\n  )\n}\n\nexport function PlanPage() {\n  const { planId = '' } = useParams()\n  const id = Number(planId)\n  const [plan, setPlan] = useState<Plan | null>(null)\n  const [papers, setPapers] = useState<Paper[]>([])\n  const [error, setError] = useState('')\n  const [query, setQuery] = useState('')\n  const [statusFilter, setStatusFilter] = useState<'' | PaperStatus>('')\n  const [drawer, setDrawer] = useState<'' | 'import' | 'share' | 'glossary' | 'settings'>('')\n  const timer = useRef<number | null>(null)\n\n  const load = useCallback(async () => {\n    try {\n      const [p, list] = await Promise.all([api.plan(id), api.papers(id)])\n      setPlan(p); setPapers(list); setError('')\n    } catch (e) { setError(e instanceof Error ? e.message : '加载失败') }\n  }, [id])\n\n  useEffect(() => { if (Number.isFinite(id)) void load() }, [id, load])\n\n  // 只在有转换任务时轮询（无人值守的进度反馈）\n  const pending = papers.some((p) => p.conv_state === 'queued' || p.conv_state === 'doing')\n  useEffect(() => {\n    if (!pending) return\n    timer.current = window.setInterval(() => { void load() }, 3000)\n    return () => { if (timer.current) window.clearInterval(timer.current) }\n  }, [pending, load])\n\n  const shown = useMemo(() => papers.filter((p) => {\n    if (statusFilter && p.status !== statusFilter) return false\n    if (!query.trim()) return true\n    const q = query.trim().toLowerCase()\n    return (p.title || '').toLowerCase().includes(q)\n      || (p.authors || '').toLowerCase().includes(q)\n      || p.tags.some((t) => t.toLowerCase().includes(q))\n  }), [papers, query, statusFilter])\n\n  async function setStatus(p: Paper, status: PaperStatus) {\n    await api.updatePaper(p.id, { status_ } as never)\n    await load()\n  }\n  async function del(p: Paper) {\n    if (!confirm(`删除《${p.title}》？其译文、笔记与图片都会一并删除。`)) return\n    await api.deletePaper(p.id)\n    await load()\n  }\n  async function retry(pid: number) {\n    await api.retryConvert(pid)\n    await load()\n  }\n\n  return (\n    <div className=\"page\">\n      <p className=\"muted\"><Link to=\"/plans\">← 返回计划列表</Link></p>\n      <div className=\"row wrap\">\n        <h1 style={{ flex: 1 }}>{plan?.name || '计划'}</h1>\n        <button onClick={() => setDrawer('import')}>导入文献</button>\n        <button onClick={() => setDrawer('glossary')}>术语表</button>\n        <button onClick={() => setDrawer('share')}>分享</button>\n        <button className=\"ghost\" onClick={() => setDrawer('settings')}>设置</button>\n      </div>\n      {(plan?.description || plan?.goal) && (\n        <p className=\"muted\">\n          {plan.description}\n          {plan.goal ? ` · 目标 ${plan.goal} 篇` : ''}\n          {` · 共 ${papers.length} 篇，已读 ${papers.filter((p) => p.status === 'read' || p.status === 'reviewed').length}`}\n        </p>\n      )}\n\n      {error && <div className=\"banner error\">{error}</div>}\n\n      <div className=\"row wrap\" style={{ margin: '14px 0', gap: 8 }}>\n        <div style={{ flex: '1 1 220px', maxWidth: 320 }}>\n          <input placeholder=\"搜索标题 / 作者 / 标签\" value={query}\n                 onChange={(e) => setQuery(e.target.value)} />\n        </div>\n        <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as never)}\n                style={{ width: 130 }}>\n          <option value=\"\">全部状态</option>\n          {Object.entries(STATUS_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}\n        </select>\n        {pending && <span className=\"muted\">转换进行中…（自动刷新）</span>}\n      </div>\n\n      {shown.length === 0 ? (\n        <p className=\"muted\">还没有文献。点「导入文献」上传 PDF 或贴 arXiv 链接。</p>\n      ) : (\n        <table className=\"list\">\n          <thead>\n            <tr>\n              <th style={{ width: '38%' }}>标题</th>\n              <th>来源</th>\n              <th style={{ width: 90 }}>状态</th>\n              <th style={{ width: 110 }}>进度</th>\n              <th style={{ width: 100 }}>转换</th>\n              <th style={{ width: 200 }}>操作</th>\n            </tr>\n          </thead>\n          <tbody>\n            {shown.map((p) => (\n              <tr key={p.id}>\n                <td>\n                  <Link to={`/reader/${p.id}`} style={{ fontWeight: 600 }}>{p.title || `文献 #${p.id}`}</Link>\n                  <div className=\"muted\">\n                    {[p.authors, p.venue, p.year].filter(Boolean).join(' · ')}\n                  </div>\n                  {p.tags.length > 0 && (\n                    <div style={{ marginTop: 4 }}>\n                      {p.tags.map((t) => <span key={t} className=\"chip\" style={{ marginRight: 4 }}>{t}</span>)}\n                    </div>\n                  )}\n                </td>\n                <td className=\"muted\">\n                  {p.source === 'arxiv' ? `arXiv ${p.source_ref || ''}` : 'PDF'}\n                </td>\n                <td>\n                  <select value={p.status} onChange={(e) => void setStatus(p, e.target.value as PaperStatus)}\n                          style={{ fontSize: 13, padding: '3px 6px' }}>\n                    {Object.entries(STATUS_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}\n                  </select>\n                </td>\n                <td>\n                  <div className=\"progress\" title={p.progress_mode === 'manual' ? '已标记已读，进度锁定' : '随阅读滚动自动累计'}>\n                    <i style={{ width: `${p.progress}%` }} />\n                  </div>\n                  <span className=\"muted\" style={{ fontSize: 12 }}>\n                    {p.progress}%{p.progress_mode === 'manual' ? '（手动）' : ''}\n                  </span>\n                </td>\n                <td><ConvChip paper={p} onRetry={(pid) => void retry(pid)} /></td>\n                <td>\n                  <div className=\"row\" style={{ gap: 6 }}>\n                    <Link className=\"btn\" to={`/reader/${p.id}`}>精读</Link>\n                    <a className=\"btn\" href={api.exportUrl(p.id, 'dual')} target=\"_blank\" rel=\"noreferrer\">导出</a>\n                    <button className=\"danger ghost\" onClick={() => void del(p)}>删除</button>\n                  </div>\n                </td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      )}\n\n      {drawer === 'import' && (\n        <Drawer title=\"导入文献\" onClose={() => setDrawer('')}>\n          <ImportPanel planId={id} onDone={() => { setDrawer(''); void load() }} />\n        </Drawer>\n      )}\n      {drawer === 'glossary' && (\n        <Drawer title=\"术语表（本计划内生效）\" onClose={() => setDrawer('')}>\n          <GlossaryPanel planId={id} />\n        </Drawer>\n      )}\n      {drawer === 'share' && (\n        <Drawer title=\"只读分享\" onClose={() => setDrawer('')}>\n          <SharePanel planId={id} />\n        </Drawer>\n      )}\n      {drawer === 'settings' && plan && (\n        <Drawer title=\"计划设置\" onClose={() => setDrawer('')}>\n          <PlanSettings plan={plan} onSaved={() => { setDrawer(''); void load() }} />\n        </Drawer>\n      )}\n    </div>\n  )\n}\n\n/* ── 导入（⑱：PDF 上传 + arXiv 链接）────────────────────────────── */\nfunction ImportPanel({ planId, onDone }: { planId: number; onDone: () => void }) {\n  const [tab, setTab] = useState<'pdf' | 'arxiv'>('pdf')\n  const [files, setFiles] = useState<File[]>([])\n  const [tags, setTags] = useState('')\n  const [ref, setRef] = useState('')\n  const [over, setOver] = useState(false)\n  const [msg, setMsg] = useState('')\n  const [err, setErr] = useState('')\n  const [busy, setBusy] = useState(false)\n\n  async function upload() {\n    if (files.length === 0) return\n    setBusy(true); setErr(''); setMsg('')\n    try {\n      const created = await api.uploadPapers(planId, files, tags)\n      setMsg(`已加入 ${created.length} 篇，正在后台自动转换（可关闭本窗口）。`)\n      setFiles([])\n      setTimeout(onDone, 900)\n    } catch (e) { setErr(e instanceof Error ? e.message : '上传失败') }\n    finally { setBusy(false) }\n  }\n\n  async function arxiv() {\n    if (!ref.trim()) return\n    setBusy(true); setErr(''); setMsg('')\n    try {\n      await api.importArxiv(planId, ref.trim())\n      setMsg('已加入，正在后台自动转换（优先抓 arXiv 官方 HTML）。')\n      setRef('')\n      setTimeout(onDone, 900)\n    } catch (e) { setErr(e instanceof Error ? e.message : '导入失败') }\n    finally { setBusy(false) }\n  }\n\n  return (\n    <div>\n      <div className=\"tabs\">\n        <button className={tab === 'pdf' ? 'active' : ''} onClick={() => setTab('pdf')}>上传 PDF</button>\n        <button className={tab === 'arxiv' ? 'active' : ''} onClick={() => setTab('arxiv')}>arXiv 链接</button>\n      </div>\n      {err && <div className=\"banner error\">{err}</div>}\n      {msg && <div className=\"banner ok\">{msg}</div>}\n\n      {tab === 'pdf' ? (\n        <div className=\"stack\">\n          <div className={`drop ${over ? 'over' : ''}`}\n               onDragOver={(e) => { e.preventDefault(); setOver(true) }}\n               onDragLeave={() => setOver(false)}\n               onDrop={(e) => {\n                 e.preventDefault(); setOver(false)\n                 setFiles(Array.from(e.dataTransfer.files).filter((f) => f.name.toLowerCase().endsWith('.pdf')))\n               }}>\n            <div>把 PDF 拖到这里，或</div>\n            <label className=\"btn\" style={{ marginTop: 8, display: 'inline-flex' }}>\n              选择文件\n              <input type=\"file\" accept=\"application/pdf\" multiple hidden\n                     onChange={(e) => setFiles(Array.from(e.target.files || []))} />\n            </label>\n          </div>\n          {files.length > 0 && (\n            <ul style={{ margin: 0, paddingLeft: 18 }}>\n              {files.map((f) => <li key={f.name}>{f.name} <span className=\"muted\">({Math.round(f.size / 1024)} KB)</span></li>)}\n            </ul>\n          )}\n          <div className=\"field\">\n            <label>标签（逗号分隔，可选）</label>\n            <input value={tags} onChange={(e) => setTags(e.target.value)} placeholder=\"CBF, 综述\" />\n          </div>\n          <button className=\"primary\" disabled={busy || files.length === 0} onClick={() => void upload()}>\n            {busy ? '上传中…' : `上传并转换${files.length ? `（${files.length}）` : ''}`}\n          </button>\n          <p className=\"muted\">\n            转换在服务端后台进行：先解析 PDF，再把公式 LaTeX 化，然后逐块翻译。\n            同一份 PDF 解析结果会被缓存复用（重复上传不重复烧钱）。\n          </p>\n        </div>\n      ) : (\n        <div className=\"stack\">\n          <div className=\"field\" style={{ maxWidth: '100%' }}>\n            <label>arXiv 编号或链接</label>\n            <input value={ref} onChange={(e) => setRef(e.target.value)}\n                   placeholder=\"1706.03762 或 https://arxiv.org/abs/2405.04434v2\" />\n          </div>\n          <button className=\"primary\" disabled={busy || !ref.trim()} onClick={() => void arxiv()}>\n            {busy ? '导入中…' : '导入并转换'}\n          </button>\n          <p className=\"muted\">\n            优先抓 arXiv 官方 HTML：公式来自页面自带的原生 LaTeX（无需模型转换，省钱且更保真）；\n            没有 HTML 版时自动回落下载 PDF 走同一条管线。\n          </p>\n        </div>\n      )}\n    </div>\n  )\n}\n\n/* ── 术语表（⑫：v1 只做术语表对齐，计划级）──────────────────────── */\nfunction GlossaryPanel({ planId }: { planId: number }) {\n  const [rows, setRows] = useState<GlossaryEntry[]>([])\n  const [msg, setMsg] = useState('')\n  useEffect(() => { api.glossary(planId).then((r) => setRows(r.glossary)).catch(() => {}) }, [planId])\n\n  function update(i: number, patch: Partial<GlossaryEntry>) {\n    setRows((rs) => rs.map((r, j) => (j === i ? { ...r, ...patch } : r)))\n  }\n  async function save() {\n    const clean = rows.filter((r) => r.en.trim() && r.zh.trim())\n    await api.setGlossary(planId, clean)\n    setRows(clean)\n    setMsg('已保存。下次转换（或对某块「重译」）时生效。')\n  }\n  return (\n    <div className=\"stack\">\n      {msg && <div className=\"banner ok\">{msg}</div>}\n      <p className=\"muted\">\n        术语表在本计划内生效，翻译时注入提示词。同一概念在不同计划里需要各配一次。\n      </p>\n      {rows.map((r, i) => (\n        <div className=\"row\" key={i} style={{ gap: 6 }}>\n          <input value={r.en} onChange={(e) => update(i, { en: e.target.value })} placeholder=\"英文\" />\n          <input value={r.zh} onChange={(e) => update(i, { zh: e.target.value })} placeholder=\"中文\" />\n          <button className=\"ghost\" onClick={() => setRows((rs) => rs.filter((_, j) => j !== i))}>删</button>\n        </div>\n      ))}\n      <div className=\"row\">\n        <button onClick={() => setRows((rs) => [...rs, { en: '', zh: '' }])}>添加一行</button>\n        <button className=\"primary\" onClick={() => void save()}>保存</button>\n      </div>\n    </div>\n  )\n}\n\n/* ── 分享（⑩⑪：实时只读 + 可撤销 + 有效期）────────────────────── */\nfunction SharePanel({ planId }: { planId: number }) {\n  const [shares, setShares] = useState<Share[]>([])\n  const [days, setDays] = useState('0')\n  const load = useCallback(async () => {\n    try { setShares(await api.shares(planId)) } catch { /* ignore */ }\n  }, [planId])\n  useEffect(() => { void load() }, [load])\n\n  async function create() {\n    const r = await api.createShare(planId, Number(days) || 0)\n    await navigator.clipboard?.writeText(r.url).catch(() => {})\n    await load()\n  }\n\n  return (\n    <div className=\"stack\">\n      <div className=\"row wrap\" style={{ alignItems: 'flex-end' }}>\n        <div className=\"field\" style={{ maxWidth: 200 }}>\n          <label>有效期</label>\n          <select value={days} onChange={(e) => setDays(e.target.value)}>\n            <option value=\"0\">永久（可随时撤销）</option>\n            <option value=\"1\">1 天</option>\n            <option value=\"7\">7 天</option>\n            <option value=\"30\">30 天</option>\n          </select>\n        </div>\n        <button className=\"primary\" onClick={() => void create()}>创建分享链接</button>\n      </div>\n      <p className=\"muted\">\n        链接是**实时只读**视图：持链接者无需登录即可阅读本计划下的文献，读到的永远是当前版本；\n        随时可以撤销。⚠️ 公开分享等于向无鉴权者分发第三方版权内容，风险自负。\n      </p>\n      {shares.map((s) => (\n        <div className=\"card\" key={s.token} style={{ padding: '10px 12px' }}>\n          <div className=\"row wrap\" style={{ gap: 8 }}>\n            <span className={`chip ${s.state === 'active' ? 'ok' : 'danger'}`}>\n              {s.state === 'active' ? '有效' : s.state === 'expired' ? '已过期' : '已撤销'}\n            </span>\n            <span className=\"muted\">{s.expires_at ? `到期 ${s.expires_at.slice(0, 10)}` : '永久'}</span>\n            <div className=\"spacer\" />\n            {s.state === 'active' && (\n              <>\n                <button onClick={() => void navigator.clipboard?.writeText(s.url)}>复制</button>\n                <a className=\"btn\" href={`/share/${s.token}`} target=\"_blank\" rel=\"noreferrer\">预览</a>\n                <button className=\"danger ghost\"\n                        onClick={() => void api.revokeShare(s.token).then(load)}>撤销</button>\n              </>\n            )}\n          </div>\n          <div className=\"muted\" style={{ marginTop: 6, wordBreak: 'break-all' }}>{s.url}</div>\n        </div>\n      ))}\n    </div>\n  )\n}\n\n/* ── 计划设置 ────────────────────────────────────────────────────── */\nfunction PlanSettings({ plan, onSaved }: { plan: Plan; onSaved: () => void }) {\n  const [name, setName] = useState(plan.name)\n  const [desc, setDesc] = useState(plan.description || '')\n  const [goal, setGoal] = useState(plan.goal ? String(plan.goal) : '')\n\n  return (\n    <div className=\"stack\">\n      <div className=\"field\"><label>名称</label>\n        <input value={name} onChange={(e) => setName(e.target.value)} /></div>\n      <div className=\"field\"><label>说明</label>\n        <input value={desc} onChange={(e) => setDesc(e.target.value)} /></div>\n      <div className=\"field\"><label>目标篇数</label>\n        <input value={goal} onChange={(e) => setGoal(e.target.value)} type=\"number\" min={1} /></div>\n      <div className=\"row\">\n        <button className=\"primary\" onClick={() =>\n          void api.updatePlan(plan.id, { name, description: desc, goal: goal ? Number(goal) : null })\n            .then(onSaved)}>保存</button>\n        <div className=\"spacer\" />\n        <button className=\"danger\" onClick={() => {\n          if (confirm('删除整个计划？其下的文献、译文、笔记与分享链接都会删除。')) {\n            void api.deletePlan(plan.id).then(() => { window.location.href = '/plans' })\n          }\n        }}>删除计划</button>\n      </div>\n    </div>\n  )\n}\n", "file_path": "/Users/argszero/scm/github.com/argszero/papershelf/web/src/pages/Plan.tsx", "intent": "build the plan detail page with import/glossary/share drawers"}"}}]}
