import sqlite3, json, sys
sys.path.insert(0, "src")
from papershelf.pipeline.parse import _looks_like_continuation
db = sys.argv[1]; pid = int(sys.argv[2]) if len(sys.argv) > 2 else 1
c = sqlite3.connect(db); c.row_factory = sqlite3.Row
rows = [dict(r) for r in c.execute("select id,ord,type,en,coalesce(zh,'') zh,payload from blocks where paper_id=? order by ord", (pid,))]
def pay(b):
    try: return json.loads(b["payload"] or "{}")
    except Exception: return {}
BODY = {"p", "h2", "h3", "h4", "ref", "table"}
SKIP = {"band", "deco", "figure", "eq"}          # 页眉/装饰/图：不参与"半句"判据，但**能被跨过**
prev = None; prev_skipped = []
pairs = []
for r in rows:
    t = r["type"]
    if t in SKIP or pay(r).get("band"):
        if prev is not None: prev_skipped.append(r["id"])
        continue
    if t in BODY and prev is not None:
        if _looks_like_continuation(prev["en"], r["en"]):
            pairs.append((prev, r, prev_skipped[:]))
    prev = r; prev_skipped = []
print("块", len(rows), "| 半句对", len(pairs))
same = [p for p in pairs if pay(p[0]).get("page") == pay(p[1]).get("page")]
cross = [p for p in pairs if pay(p[0]).get("page") != pay(p[1]).get("page")]
print("  同页", len(same), "| 跨页", len(cross))
print()
for a, b, skipped in cross:
    print(f"[p{pay(a).get('page')} {a['id']}] …{a['en'][-58:]!r}")
    print(f"   ↳ 跳过 {skipped}")
    print(f"[p{pay(b).get('page')} {b['id']}] {b['en'][:58]!r}…")
    print(f"   中: …{a['zh'][-26:]!r}  ‖  {b['zh'][:26]!r}…")
    print()
EOF
