        """
        ids = {b.id for b in blocks}
        rows: list[str] = []
        for a, b in seams:
            a_in, b_in = a.id in ids, b.id in ids
            if not (a_in or b_in):
                continue
            tail = (a.en or "").rstrip()[-28:]
            head = (b.en or "").lstrip()[:28]
            if a_in and b_in:
                rows.append(
                    f"- {a.id} → {b.id}：这是**同一句话**（排版把它切成了两块），"
                    f"上一块的结尾是「…{tail}」、下一块的开头是「{head}…」。"
